sp_widget.client_script:
api.controller = function($scope) {
  var c = this;

  c.showModal = false;
  c.bookingConfirmed = false;
  c.isSubmitting = false;
  c.selectedActivity = {};

  if (c.data.isLoggedIn) {
    c.data.guestName = c.data.userName;
    c.data.guestEmail = c.data.userEmail;
  }

  // Pre-select first activity if available
  if (c.data.activities && c.data.activities.length > 0) {
    c.data.selectedActivityId = c.data.activities[0].sys_id;
    c.selectedActivity = c.data.activities[0];
  }

  c.onSelectActivity = function(act) {
    c.selectedActivity = act;
    c.data.selectedActivityId = act.sys_id;
    c.data.ruleWarning = '';
    c.data.bookingError = '';
  };

  c.canSubmit = function() {
    return c.data.selectedActivityId && 
           c.data.reservationNumber && 
           c.data.guestName && 
           c.data.guestEmail;
  };

  c.openConfirmModal = function() {
    if (c.canSubmit()) {
      c.showModal = true;
      c.bookingConfirmed = false;
    }
  };

  c.closeModal = function() {
    c.showModal = false;
  };

  c.confirmBooking = function() {
    c.isSubmitting = true;
    c.data.action = 'bookActivity';
    c.server.update().then(function() {
      c.isSubmitting = false;
      if (c.data.bookingSuccess) {
        c.bookingConfirmed = true;
      }
    });
  };

  c.resetForm = function() {
    c.showModal = false;
    c.bookingConfirmed = false;
    c.data.reservationNumber = '';
    c.data.bookingError = '';
    c.data.ruleWarning = '';
  };
};

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600;700&family=Inter:wght@400;500;600&display=swap');

.hotel-sports-widget {
  --green: #1f3a30;
  --green-dark: #162a22;
  --green-soft: #e8eee9;
  --sand: #e6c79c;
  --sand-dark: #d4b07c;
  --cream: #faf6ef;
  --white: #ffffff;
  --text: #2a2d29;
  --muted: #6f756f;
  --line: #e7e1d4;
  --radius: 8px;
  --shadow: 0 10px 30px rgba(31, 58, 48, .08);
  --serif: 'Cormorant Garamond', Georgia, serif;
  --sans: 'Inter', system-ui, sans-serif;

  font-family: var(--sans);
  color: var(--text);
  background: var(--cream);
  min-height: 100vh;
  padding-bottom: 60px;
}

.hotel-sports-widget h1, .hotel-sports-widget h2, .hotel-sports-widget h3 {
  font-family: var(--serif);
  color: var(--green);
  font-weight: 600;
}

.hotel-sports-widget .eyebrow {
  font-size: .72rem;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 500;
  display: block;
  margin-bottom: 6px;
}

.hotel-sports-widget .page-banner {
  background: var(--green);
  color: var(--white);
  padding: 50px 20px;
  text-align: center;
}
.hotel-sports-widget .page-banner h1 { color: var(--white); font-size: 2.8rem; margin: 0; }
.hotel-sports-widget .page-banner p { color: rgba(255,255,255,.75); margin-top: 8px; font-size: 1rem; }
.hotel-sports-widget .page-banner .eyebrow { color: var(--sand); }

.hotel-sports-widget .booking-section { padding: 40px 15px; }
.hotel-sports-widget .booking-container { max-width: 1100px; margin: 0 auto; }

.hotel-sports-widget .form-layout {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  gap: 30px;
  align-items: start;
}
@media (max-width: 900px) {
  .hotel-sports-widget .form-layout { grid-template-columns: 1fr; }
}

.hotel-sports-widget .form-card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 34px;
}

.hotel-sports-widget .form-title { font-size: 2rem; margin: 0 0 4px; }
.hotel-sports-widget .form-sub { color: var(--muted); font-size: .9rem; margin-bottom: 24px; }

.hotel-sports-widget .user-status-banner {
  background: var(--green-soft);
  border: 1px solid #c2d6c6;
  color: var(--green);
  padding: 10px 16px;
  border-radius: var(--radius);
  margin-bottom: 20px;
  font-size: .88rem;
  display: flex;
  gap: 10px;
  align-items: center;
}
.hotel-sports-widget .user-status-banner.guest {
  background: #fdf6e9;
  border-color: #f1ddb6;
  color: #8a6420;
}

/* Activity Cards List */
.hotel-sports-widget .activity-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.hotel-sports-widget .activity-card {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 16px 20px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--cream);
  cursor: pointer;
  transition: .2s;
  margin: 0;
}
.hotel-sports-widget .activity-card:hover {
  border-color: var(--sand-dark);
  background: var(--white);
}
.hotel-sports-widget .activity-card.selected {
  border-color: var(--green);
  background: var(--white);
  box-shadow: 0 0 0 2px var(--green);
}
.hotel-sports-widget .activity-card input[type="radio"] {
  accent-color: var(--green);
  width: 20px;
  height: 20px;
  cursor: pointer;
}
.hotel-sports-widget .activity-card .info { flex: 1; }
.hotel-sports-widget .activity-card h3 {
  font-size: 1.15rem;
  font-family: var(--sans);
  font-weight: 600;
  margin: 0 0 4px;
}
.hotel-sports-widget .activity-card .when {
  font-size: .82rem;
  color: var(--muted);
}
.hotel-sports-widget .activity-card .rate {
  font-family: var(--serif);
  font-size: 1.5rem;
  color: var(--green);
  font-weight: 700;
}

.hotel-sports-widget .form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}
@media (max-width: 600px) {
  .hotel-sports-widget .form-grid { grid-template-columns: 1fr; }
}

.hotel-sports-widget .field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.hotel-sports-widget .field.full { grid-column: 1 / -1; }
.hotel-sports-widget .field label {
  font-size: .72rem;
  letter-spacing: .12em;
  text-transform: uppercase;
  font-weight: 600;
  color: var(--green);
}
.hotel-sports-widget .field label .req { color: #b4483a; }
.hotel-sports-widget .field input {
  padding: 11px 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--cream);
  font-size: .92rem;
  outline: none;
  transition: .2s;
}
.hotel-sports-widget .field input:focus {
  border-color: var(--sand-dark);
  background: var(--white);
  box-shadow: 0 0 0 3px rgba(230,199,156,.3);
}
.hotel-sports-widget .field small { color: var(--muted); font-size: .78rem; }

/* Buttons */
.hotel-sports-widget .btn {
  display: inline-block;
  padding: 13px 24px;
  border-radius: var(--radius);
  font-size: .78rem;
  letter-spacing: .12em;
  text-transform: uppercase;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid transparent;
  transition: .2s;
  text-align: center;
}
.hotel-sports-widget .btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.hotel-sports-widget .btn-green {
  background: var(--green);
  color: var(--white);
}
.hotel-sports-widget .btn-green:hover:not(:disabled) {
  background: var(--green-dark);
  transform: translateY(-2px);
}
.hotel-sports-widget .btn-sand {
  background: var(--sand);
  color: var(--green);
}
.hotel-sports-widget .btn-sand:hover:not(:disabled) {
  background: var(--sand-dark);
}
.hotel-sports-widget .btn-outline {
  border-color: var(--green);
  color: var(--green);
  background: transparent;
}
.hotel-sports-widget .btn-outline:hover {
  background: var(--green);
  color: var(--white);
}
.hotel-sports-widget .btn-block { width: 100%; }

/* Summary */
.hotel-sports-widget .summary {
  background: var(--green);
  color: var(--white);
  border-radius: var(--radius);
  padding: 28px;
  position: sticky;
  top: 30px;
}
.hotel-sports-widget .summary h3 { color: var(--white); margin: 0 0 16px; font-size: 1.5rem; }
.hotel-sports-widget .summary .eyebrow { color: var(--sand); }

.hotel-sports-widget .summary-row {
  display: flex;
  justify-content: space-between;
  padding: 10px 0;
  border-bottom: 1px solid rgba(255,255,255,.14);
  font-size: .88rem;
  color: rgba(255,255,255,.8);
}
.hotel-sports-widget .summary-row strong { color: var(--white); font-weight: 600; }

.hotel-sports-widget .summary-total {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin: 22px 0 16px;
}
.hotel-sports-widget .summary-total span { font-size: .72rem; letter-spacing: .14em; text-transform: uppercase; color: var(--sand); }
.hotel-sports-widget .summary-total strong { font-family: var(--serif); font-size: 2.2rem; color: var(--white); }

.hotel-sports-widget .summary .note {
  font-size: .75rem;
  color: rgba(255,255,255,.65);
  margin-top: 14px;
  line-height: 1.4;
}

/* Alerts */
.hotel-sports-widget .alert {
  padding: 12px 16px;
  border-radius: var(--radius);
  font-size: .86rem;
  margin-bottom: 18px;
  display: flex;
  gap: 10px;
  align-items: center;
  border-left: 4px solid;
}
.hotel-sports-widget .alert.warn {
  background: #fbf1dc;
  border-color: var(--sand-dark);
  color: #7a5a1c;
}
.hotel-sports-widget .alert.error {
  background: #f8e4e0;
  border-color: #b4483a;
  color: #8a3a2f;
}

/* Modal */
.hotel-sports-widget .custom-modal-backdrop {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(22,42,34,.65);
  z-index: 1050;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}
.hotel-sports-widget .custom-modal {
  background: var(--white);
  border-radius: 12px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 25px 60px rgba(0,0,0,.25);
  overflow: hidden;
}
.hotel-sports-widget .dialog-body { padding: 32px; }
.hotel-sports-widget .dialog-total {
  font-family: var(--serif);
  font-size: 2.8rem;
  color: var(--green);
  font-weight: 700;
  margin: 8px 0 16px;
}
.hotel-sports-widget .summary-row.dark {
  color: var(--muted);
  border-color: var(--line);
}
.hotel-sports-widget .summary-row.dark strong { color: var(--text); }
.hotel-sports-widget .dialog-note {
  color: var(--muted);
  font-size: .82rem;
  margin-top: 16px;
}
.hotel-sports-widget .dialog-actions {
  display: flex;
  gap: 12px;
  justify-content: flex-end;
  margin-top: 24px;
}
.hotel-sports-widget .res-num-box {
  background: var(--cream);
  border: 2px dashed var(--sand-dark);
  padding: 16px;
  border-radius: 8px;
  text-align: center;
  margin-top: 14px;
}
.hotel-sports-widget .res-num-box small {
  text-transform: uppercase;
  letter-spacing: .12em;
  color: var(--muted);
  font-size: .7rem;
}
.hotel-sports-widget .res-num-box .res-num {
  font-family: var(--serif);
  font-size: 2rem;
  font-weight: 700;
  color: var(--green);
  margin-top: 4px;
}

sp_widget.script:
(function() {
  data.isLoggedIn = gs.isLoggedIn();
  data.userId = gs.getUserID();
  data.userName = gs.getUserDisplayName();
  data.userEmail = gs.getUser().getEmail();

  // 1. Fetch Sports Activities directly from Database
  data.activities = [];
  var actGr = new GlideRecord('x_2206701_hotel_0_sports_activities');
  actGr.orderBy('rate');
  actGr.query();
  while (actGr.next()) {
    data.activities.push({
      sys_id: actGr.getUniqueValue(),
      name: actGr.getValue('activity_name') || actGr.getDisplayValue(),
      rate: parseFloat(actGr.getValue('rate')) || 0,
      schedule: actGr.getDisplayValue('activity_date_and_time') || actGr.getValue('activity_date_and_time') || 'Daily Session · Available Today'
    });
  }

  // Fallback defaults if table has no records yet
  if (data.activities.length === 0) {
    data.activities = [
      { sys_id: 'snorkeling_tour', name: 'Snorkeling Tour', rate: 45.00, schedule: 'Daily · 9:00 AM' },
      { sys_id: 'paddleboarding', name: 'Paddleboarding', rate: 35.00, schedule: 'Daily · 2:00 PM' },
      { sys_id: 'sunset_sailing', name: 'Sunset Sailing', rate: 80.00, schedule: 'Daily · 5:00 PM' },
      { sys_id: 'kayaking', name: 'Guided Kayaking', rate: 30.00, schedule: 'Daily · 8:00 AM' }
    ];
  }

  // 2. Handle Booking Action
  if (input && input.action === 'bookActivity') {
    var pricingUtil = new x_2206701_hotel_0.PricingUtils();

    // Enforce Rule: Only one sports activity per booking (Cauban's function)
    var singleCheck = pricingUtil.validateSingleSportsActivity([input.selectedActivityId]);
    if (!singleCheck.valid) {
      data.bookingSuccess = false;
      data.bookingError = singleCheck.message;
      return;
    }

    // Call Cauban's Pricing calculation
    var actPricing = pricingUtil.calculateSportsActivity(input.selectedActivityId);

    // Generate unique Activity Reference
    var refNum = 'ACT-' + Math.floor(100000 + Math.random() * 900000);
    data.bookingSuccess = true;
    data.activityBookingRef = refNum;
    data.confirmedRate = actPricing.ok ? actPricing.rate : 0;
  }
})();
